body { margin: 0; font: 16px sans-serif; background: #0e0e10; color: #efeff1 }
header { display: flex; align-items: center; gap: 8px; padding: 8px }
header img { width: 36px; height: 36px; border-radius: 50% }
h1 { font-size: 18px; margin: 0 }
header p { margin: 0; color: #adadb8 }
.page { display: flex; gap: 16px; padding: 0 8px }
.stage { flex: 1; min-width: 0 }
video { width: 100%; height: 360px; background: #000; display: block }
#chat { width: 296px; flex: none }
#chat h2 { font-size: 16px; margin: 0 0 4px }
#log { height: 324px; overflow-y: auto }
#log > div { padding: 0 }
.author { font-weight: bold }
.badge, .emote { width: 18px; height: 18px; vertical-align: middle }
form { display: flex; gap: 8px; margin-top: 4px }
input { flex: 1; min-width: 0 }

const log = document.getElementById('log');
const badge = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 18 18'%3E%3Crect width='18' height='18' rx='4' fill='%2300a86b'/%3E%3C/svg%3E";
const emote = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 18 18'%3E%3Ccircle cx='9' cy='9' r='8' fill='%2335d0ff'/%3E%3C/svg%3E";
// Post a message: an optional badge, the author in their colour, the
// words, and :glow: as a small picture.
function post(author, color, words, moderator) {
  const row = document.createElement('div');
  if (moderator) {
    const b = document.createElement('img');
    b.className = 'badge'; b.alt = 'moderator'; b.src = badge;
    row.append(b, ' ');
  }
  const who = document.createElement('span');
  who.className = 'author'; who.style.color = color; who.textContent = author;
  row.append(who, ': ');
  const parts = words.split(':glow:');
  parts.forEach((part, i) => {
    if (i > 0) {
      const e = document.createElement('img');
      e.className = 'emote'; e.alt = ':glow:'; e.src = emote;
      row.append(e);
    }
    row.append(part);
  });
  log.append(row);
  while (log.children.length > 100) log.firstElementChild.remove();
  log.scrollTop = log.scrollHeight;
}
window.post = post;
const people = [['ada', '#ff7f50', true], ['bea', '#9acd32', false], ['cy', '#da70d6', false]];
const lines = ['the water is glowing :glow:', 'that blue is unreal', 'how deep is the camera?',
               'hello from the harbour', ':glow: :glow:', 'the tide is coming in'];
let n = 0;
function next() {
  const [who, color, mod] = people[n % people.length];
  post(who, color, lines[n % lines.length] + ' #' + (n + 1), mod);
  n++;
}
for (let i = 0; i < 6; i++) next();
if (!location.search.includes('quiet')) setInterval(next, 1500);
document.getElementById('send').addEventListener('submit', event => {
  event.preventDefault();
  const field = document.getElementById('message');
  const words = field.value.trim();
  if (words) post('you', '#35d0ff', words, false);
  field.value = '';
});
